insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":6239,"materia":"ling","nivel":3,"enunciado":"Um meme usa uma frase famosa de um filme, fora do contexto original, para criar humor. O recurso usado é a:","opcoes":["Intertextualidade","Onomatopeia","Concordância","Metrificação"],"explicacao":"Um texto dialoga com outro já conhecido."},{"id":6240,"materia":"ling","nivel":4,"enunciado":"Alberto Caeiro, Ricardo Reis e Álvaro de Campos são:","opcoes":["Heterônimos do poeta Fernando Pessoa","Personagens dos romances de Machado de Assis","Poetas do Arcadismo mineiro","Pseudônimos de Camões"],"explicacao":"Cada heterônimo tem estilo e biografia próprios."},{"id":6241,"materia":"ling","nivel":2,"enunciado":"Numa mensagem a um amigo, alguém escreve “tô chegando, vc vem?”. Essa linguagem informal é:","opcoes":["Adequada à situação de comunicação","Errada em qualquer situação de comunicação, sempre","Própria de documentos oficiais","Exclusiva da escrita formal"],"explicacao":"A adequação depende do contexto e do interlocutor."},{"id":6242,"materia":"ling","nivel":2,"enunciado":"Debaixo de uma tempestade, sem guarda-chuva, alguém diz: “Que dia lindo para passear!”. A figura de linguagem é a:","opcoes":["Ironia","Comparação","Onomatopeia","Pleonasmo"],"explicacao":"Diz o contrário do que pensa."},{"id":6243,"materia":"ling","nivel":3,"enunciado":"Sobre a Libras, é correto afirmar que:","opcoes":["É uma língua com gramática própria","É apenas mímica","É o português escrito com as mãos, letra por letra","É igual em todos os países"],"explicacao":"Cada país tem sua língua de sinais."},{"id":6244,"materia":"ling","nivel":2,"enunciado":"Um infográfico combina:","opcoes":["Texto verbal e elementos visuais, como gráficos e ícones","Apenas texto corrido","Somente fotografias, sem nenhum texto ou legenda","Só números, sem explicação"],"explicacao":"Facilita a compreensão rápida de dados."},{"id":6245,"materia":"mat","nivel":2,"enunciado":"A tarifa de energia é de R$ 0,80 por kWh. Uma casa consumiu 150 kWh no mês. O valor da conta é:","opcoes":["R$ 120,00","R$ 150,00","R$ 187,50","R$ 80,00"],"explicacao":"150 × 0,80."},{"id":6246,"materia":"mat","nivel":3,"enunciado":"Uma torneira pingando desperdiça 40 litros por dia. Em 30 dias, isso equivale a:","opcoes":["1,2 m³","12 m³","0,12 m³","120 m³"],"explicacao":"1.200 L = 1,2 m³."},{"id":6247,"materia":"mat","nivel":2,"enunciado":"Num gráfico de setores, uma fatia que representa 25% do total corresponde a um ângulo de:","opcoes":["90°","25°","45°","180°"],"explicacao":"25% de 360°."},{"id":6248,"materia":"mat","nivel":3,"enunciado":"A média de 5 números é 8. Acrescentando o número 14, a nova média passa a ser:","opcoes":["9","11","8,5","10"],"explicacao":"(40 + 14) ÷ 6."},{"id":6249,"materia":"mat","nivel":3,"enunciado":"Quanto é 40% de 30%?","opcoes":["12%","70%","10%","1,2%"],"explicacao":"0,4 × 0,3 = 0,12."},{"id":6250,"materia":"mat","nivel":4,"enunciado":"Uma caixa tem 2 bolas vermelhas e 3 azuis. Tirando duas bolas, com reposição, a chance de as duas serem vermelhas é:","opcoes":["4/25","2/5","1/10","4/10"],"explicacao":"2/5 × 2/5."},{"id":6251,"materia":"mat","nivel":3,"enunciado":"Com uma internet de 10 MB/s, quanto tempo leva para baixar um arquivo de 1,2 GB (1 GB = 1.000 MB)?","opcoes":["2 minutos","12 segundos","20 minutos","1 minuto"],"explicacao":"1.200 ÷ 10 = 120 s."},{"id":6252,"materia":"mat","nivel":4,"enunciado":"Quanto vale a soma 1 + 2 + 4 + 8 + 16 + 32 + 64?","opcoes":["127","128","126","64"],"explicacao":"Soma de PG: 2⁷ − 1."},{"id":6253,"materia":"mat","nivel":4,"enunciado":"Um voo sai de Brasília (UTC−3) às 10h e dura 12 horas até Lisboa (UTC+0). No horário de Lisboa, ele chega:","opcoes":["À 1h do dia seguinte","Às 22h","Às 19h","Às 10h do dia seguinte"],"explicacao":"Chega às 22h de Brasília, que são 1h em Lisboa."},{"id":6254,"materia":"mat","nivel":3,"enunciado":"A mediana do conjunto 3, 5, 7, 9 é:","opcoes":["6","5","7","24"],"explicacao":"Com quantidade par, é a média dos dois centrais."},{"id":6255,"materia":"fis","nivel":2,"enunciado":"No verão, roupas claras são mais indicadas porque:","opcoes":["Refletem mais a radiação do Sol","Absorvem mais calor","Produzem frio","Conduzem melhor a eletricidade do corpo para o ar"],"explicacao":"Cores escuras absorvem mais radiação."},{"id":6256,"materia":"fis","nivel":3,"enunciado":"O cobertor nos mantém aquecidos porque:","opcoes":["É isolante e reduz a perda do calor do corpo","Produz calor sozinho, por causa do tecido","Absorve o frio","Conduz bem o calor"],"explicacao":"Ele não esquenta: dificulta a saída do calor."},{"id":6257,"materia":"fis","nivel":2,"enunciado":"Ao esfregar as mãos para aquecê-las, transformamos energia:","opcoes":["Mecânica em térmica","Térmica em química","Elétrica em luminosa","Nuclear em mecânica"],"explicacao":"O atrito gera calor."},{"id":6258,"materia":"fis","nivel":3,"enunciado":"Em dias secos, levamos “choquinhos” ao tocar na maçaneta. Isso ocorre por:","opcoes":["Eletrização por atrito","Magnetismo da Terra","Radiação solar","Dilatação térmica"],"explicacao":"O corpo acumula carga ao atritar com roupas e tapetes."},{"id":6259,"materia":"fis","nivel":4,"enunciado":"Um pássaro pousa num fio de alta tensão e não leva choque porque:","opcoes":["Não há diferença de potencial entre suas patas","O pássaro é um isolante perfeito, por causa das penas","A corrente no fio é zero","As penas descarregam a energia"],"explicacao":"Sem diferença de potencial, não passa corrente pelo corpo."},{"id":6260,"materia":"fis","nivel":3,"enunciado":"O trovão foi ouvido 3 segundos depois do relâmpago. Com o som a 340 m/s, o raio caiu a cerca de:","opcoes":["1.020 m","340 m","113 m","3.400 m"],"explicacao":"340 × 3."},{"id":6261,"materia":"fis","nivel":2,"enunciado":"Disjuntores e fusíveis servem para:","opcoes":["Proteger a instalação de correntes excessivas","Aumentar a potência dos aparelhos ligados na tomada","Economizar energia","Gerar eletricidade"],"explicacao":"Desligam o circuito em caso de sobrecarga."},{"id":6262,"materia":"fis","nivel":4,"enunciado":"Um satélite em órbita não cai na Terra porque:","opcoes":["Está em queda livre, mas com velocidade lateral suficiente para contornar a Terra","Não há gravidade no espaço","Tem motores ligados o tempo todo para não cair na Terra, que o atrai sempre","É mais leve que o ar"],"explicacao":"Ele “cai” continuamente em volta da Terra."},{"id":6263,"materia":"qui","nivel":4,"enunciado":"Em países frios, joga-se sal nas estradas congeladas porque o sal:","opcoes":["Abaixa a temperatura de fusão da água","Aumenta a temperatura do ar acima da estrada","Aquece o asfalto por reação","Torna o gelo mais duro"],"explicacao":"Efeito coligativo (crioscopia)."},{"id":6264,"materia":"qui","nivel":4,"enunciado":"A água salgada ferve a uma temperatura um pouco acima de 100 °C por causa da:","opcoes":["Ebulioscopia, efeito do soluto","Sublimação","Fotossíntese","Combustão"],"explicacao":"O soluto eleva o ponto de ebulição."},{"id":6265,"materia":"qui","nivel":4,"enunciado":"Pingar limão no peixe diminui o cheiro forte porque o ácido:","opcoes":["Reage com as aminas, que são básicas","Evapora o peixe","Mata o cheiro por congelamento das moléculas","Aumenta o pH do peixe"],"explicacao":"Reação de neutralização."},{"id":6266,"materia":"qui","nivel":2,"enunciado":"O leite de magnésia, usado contra a acidez do estômago, é:","opcoes":["Uma base","Um ácido forte","Um sal neutro","Um metal puro"],"explicacao":"Hidróxido de magnésio."},{"id":6267,"materia":"qui","nivel":2,"enunciado":"Para haver fogo, é preciso o “triângulo do fogo”, formado por:","opcoes":["Combustível, comburente (oxigênio) e calor","Água, terra e ar em proporções iguais","Gás, sal e luz","Ferro, zinco e cobre"],"explicacao":"Retirar um dos três apaga o fogo."},{"id":6268,"materia":"qui","nivel":3,"enunciado":"O extintor de gás carbônico apaga o fogo principalmente por:","opcoes":["Abafamento, afastando o oxigênio","Aquecimento","Adição de combustível","Aumento da pressão do ar em volta das chamas"],"explicacao":"Indicado para equipamentos elétricos."},{"id":6269,"materia":"qui","nivel":2,"enunciado":"O gás de efeito estufa mais emitido pelas atividades humanas é o:","opcoes":["Gás carbônico (CO₂)","Oxigênio (O₂)","Nitrogênio (N₂)","Hélio (He)"],"explicacao":"Vem da queima de combustíveis fósseis e do desmatamento."},{"id":6270,"materia":"qui","nivel":4,"enunciado":"Ao misturar cal virgem (CaO) com água, a mistura esquenta muito porque a reação é:","opcoes":["Exotérmica","Endotérmica","Nuclear","Física, sem reação"],"explicacao":"Forma cal hidratada, Ca(OH)₂."},{"id":6271,"materia":"qui","nivel":4,"enunciado":"No teste de chama, cada metal dá uma cor diferente porque:","opcoes":["Os elétrons excitados liberam luz ao voltar a níveis de menor energia","O fogo muda de cor sozinho, conforme a temperatura do ambiente em volta da chama","O metal derrete","Os núcleos se dividem"],"explicacao":"Modelo atômico de Bohr."},{"id":6272,"materia":"qui","nivel":3,"enunciado":"Pequenos fragmentos de plástico, que poluem mares e já aparecem até na água potável, são os:","opcoes":["Microplásticos","Polímeros naturais","Sais minerais","Isótopos"],"explicacao":"Vêm da degradação de plásticos maiores."},{"id":6273,"materia":"bio","nivel":3,"enunciado":"Interromper o antibiótico assim que os sintomas somem, antes do fim do tratamento, pode:","opcoes":["Favorecer a sobrevivência de bactérias mais resistentes","Curar mais rápido","Fortalecer o remédio que já foi tomado nos primeiros dias","Eliminar todos os vírus"],"explicacao":"As bactérias que sobram podem ser as mais resistentes."},{"id":6274,"materia":"bio","nivel":2,"enunciado":"Numa região, as cobras foram caçadas até quase sumirem. É esperado que:","opcoes":["Aumente a população de ratos","Diminua a população de ratos","As plantas desapareçam","Nada mude"],"explicacao":"Os ratos perdem seu predador."},{"id":6275,"materia":"bio","nivel":4,"enunciado":"Os “rios voadores”, que levam umidade da Amazônia para o Centro-Sul, mostram que o desmatamento da floresta pode:","opcoes":["Reduzir as chuvas em outras regiões do país","Aumentar as chuvas no Sudeste e no Centro-Oeste do país","Esfriar o Nordeste","Aumentar a umidade do Sul"],"explicacao":"A transpiração das árvores alimenta essas correntes."},{"id":6276,"materia":"bio","nivel":2,"enunciado":"O “teste do pezinho”, feito no recém-nascido, serve para:","opcoes":["Detectar cedo doenças genéticas e metabólicas","Medir o tamanho do pé","Descobrir o tipo sanguíneo dos pais do recém-nascido","Vacinar o bebê"],"explicacao":"Ex.: fenilcetonúria e hipotireoidismo congênito."},{"id":6277,"materia":"bio","nivel":2,"enunciado":"No exame de paternidade por DNA, compara-se:","opcoes":["O material genético do filho com o do suposto pai","Apenas o tipo sanguíneo do filho e da mãe, sem o do pai","A cor dos olhos","As impressões digitais"],"explicacao":"Metade do DNA do filho vem do pai."},{"id":6278,"materia":"bio","nivel":3,"enunciado":"O teste de gravidez detecta o hormônio:","opcoes":["hCG (gonadotrofina coriônica)","Insulina","Adrenalina","Testosterona"],"explicacao":"Produzido pela placenta."},{"id":6279,"materia":"bio","nivel":3,"enunciado":"Usar joaninhas para combater pulgões numa plantação é exemplo de:","opcoes":["Controle biológico","Uso de agrotóxicos","Transgenia","Queimada controlada"],"explicacao":"Reduz o uso de produtos químicos."},{"id":6280,"materia":"bio","nivel":4,"enunciado":"O oxigênio liberado na fotossíntese vem da:","opcoes":["Molécula de água","Molécula de gás carbônico","Glicose","Clorofila"],"explicacao":"A água é quebrada na fase clara (fotólise)."},{"id":6281,"materia":"bio","nivel":4,"enunciado":"Plantar feijão ou soja ajuda a enriquecer o solo com nitrogênio por causa de:","opcoes":["Bactérias fixadoras de nitrogênio nas raízes","Fungos que produzem oxigênio","Raízes que absorvem gás carbônico do ar e o transformam","Folhas que retêm água"],"explicacao":"Simbiose com bactérias do gênero Rhizobium."},{"id":6282,"materia":"his","nivel":3,"enunciado":"Após 1945, vários países da África e da Ásia deixaram de ser colônias europeias. Esse processo é chamado de:","opcoes":["Descolonização","Colonização","Feudalização","Mercantilismo"],"explicacao":"Ex.: Índia (1947) e Argélia (1962)."},{"id":6283,"materia":"his","nivel":3,"enunciado":"No início da colonização, Portugal dividiu o Brasil em grandes faixas de terra entregues a donatários. Eram as:","opcoes":["Capitanias hereditárias","Sesmarias urbanas","Províncias imperiais","Regiões metropolitanas"],"explicacao":"Criadas em 1534."},{"id":6284,"materia":"geo","nivel":4,"enunciado":"Num mapa topográfico, curvas de nível muito próximas umas das outras indicam um terreno:","opcoes":["Íngreme","Plano","Alagado","Desértico"],"explicacao":"Grande variação de altitude em pouca distância."},{"id":6285,"materia":"geo","nivel":2,"enunciado":"Empresas que têm sede num país e filiais em vários outros são chamadas de:","opcoes":["Transnacionais (multinacionais)","Estatais locais","Cooperativas","Microempresas"],"explicacao":"São marcas da globalização."},{"id":6286,"materia":"geo","nivel":4,"enunciado":"A grande concentração urbana entre as metrópoles de São Paulo e Rio de Janeiro forma uma:","opcoes":["Megalópole","Vila rural","Cidade média isolada","Reserva ambiental"],"explicacao":"Ligadas pelo eixo da Via Dutra."},{"id":6287,"materia":"geo","nivel":3,"enunciado":"Ricos em condomínios fechados e pobres em áreas sem infraestrutura, numa mesma cidade, é exemplo de:","opcoes":["Segregação socioespacial","Êxodo rural","Conurbação","Desertificação"],"explicacao":"Reflete a desigualdade no espaço urbano."},{"id":6288,"materia":"geo","nivel":3,"enunciado":"A mata ciliar, nas margens dos rios, é importante porque:","opcoes":["Protege os rios contra o assoreamento","Aumenta a erosão e o transporte de terra para o leito","Seca os rios","Impede a pesca"],"explicacao":"Segura o solo e filtra a água."},{"id":6289,"materia":"geo","nivel":3,"enunciado":"O pré-sal é:","opcoes":["Uma grande reserva de petróleo em águas muito profundas","Uma salina no litoral do Rio Grande do Norte","Um tipo de solo do Cerrado","Um bioma costeiro"],"explicacao":"Fica abaixo de uma camada de sal no fundo do mar."},{"id":6290,"materia":"geo","nivel":3,"enunciado":"O coeficiente de Gini mede:","opcoes":["A desigualdade na distribuição de renda","A altitude média de um país em relação ao mar","A quantidade de chuva","A taxa de natalidade"],"explicacao":"Quanto mais perto de 1, maior a desigualdade."},{"id":6291,"materia":"geo","nivel":3,"enunciado":"A agência da ONU que protege e ajuda os refugiados é o:","opcoes":["ACNUR","FMI","OMC","Unesco"],"explicacao":"Alto Comissariado das Nações Unidas para Refugiados."},{"id":6292,"materia":"fil","nivel":4,"enunciado":"Para Santo Agostinho, o mal no mundo é resultado:","opcoes":["Do mau uso do livre-arbítrio humano","Da vontade de Deus, que deseja o sofrimento","Do acaso total","Das estrelas"],"explicacao":"O mal seria ausência de bem."},{"id":6293,"materia":"fil","nivel":2,"enunciado":"A socialização primária, em que a criança aprende os primeiros valores, ocorre principalmente na:","opcoes":["Família","Universidade","Empresa","Política"],"explicacao":"A escola e o trabalho são socialização secundária."},{"id":6294,"materia":"fil","nivel":2,"enunciado":"O Movimento dos Trabalhadores Rurais Sem Terra (MST) luta principalmente pela:","opcoes":["Reforma agrária","Privatização de empresas","Construção de rodovias","Redução de impostos"],"explicacao":"Defende a distribuição de terras."},{"id":6295,"materia":"fil","nivel":4,"enunciado":"Entre os contratualistas, quem defendeu o direito do povo de resistir a um governo que viola a vida, a liberdade e a propriedade foi:","opcoes":["John Locke","Thomas Hobbes","Maquiavel","Platão"],"explicacao":"Influenciou as revoluções liberais."},{"id":6296,"materia":"ling","nivel":2,"enunciado":"“A cidade dormia. Só o vento, inquieto, andava pelas ruas.” Dar ao vento ações humanas é a figura chamada:","opcoes":["Personificação (prosopopeia)","Hipérbole","Eufemismo","Pleonasmo"],"explicacao":"O vento “anda” e é “inquieto”, como uma pessoa."},{"id":6297,"materia":"ling","nivel":1,"enunciado":"“Já te liguei um milhão de vezes hoje!” A figura de linguagem é a:","opcoes":["Hipérbole","Eufemismo","Metonímia","Antítese"],"explicacao":"Exagero para dar ênfase."},{"id":6298,"materia":"ling","nivel":1,"enunciado":"A manchete “Chuva deixa 200 desalojados em Recife” tem como função principal:","opcoes":["Informar um fato","Emocionar com rimas","Testar o canal de comunicação","Explicar a própria linguagem"],"explicacao":"Função referencial."},{"id":6299,"materia":"ling","nivel":2,"enunciado":"Um manual de instruções costuma se caracterizar por:","opcoes":["Verbos no imperativo e passos em sequência","Rimas e versos","Narrador em primeira pessoa contando suas lembranças","Opinião do autor"],"explicacao":"Ex.: “Ligue o aparelho”, “Pressione o botão”."},{"id":6300,"materia":"ling","nivel":2,"enunciado":"A crônica é um gênero que geralmente:","opcoes":["Parte de um fato do cotidiano, com linguagem leve","É sempre um poema com rima","Apresenta só dados estatísticos e tabelas oficiais","É um documento oficial"],"explicacao":"Publicada em jornais e revistas."},{"id":6301,"materia":"ling","nivel":2,"enunciado":"Numa placa, em inglês: “The store is closed on Sundays.” Isso quer dizer que:","opcoes":["A loja fecha aos domingos","A loja abre só aos domingos","A loja fechou para sempre","A loja está em reforma"],"explicacao":"Closed = fechada; Sundays = domingos."},{"id":6302,"materia":"ling","nivel":2,"enunciado":"Em espanhol, na frase “Ayer fui al mercado”, a palavra “ayer” significa:","opcoes":["Ontem","Amanhã","Hoje","Sempre"],"explicacao":"Mañana = amanhã; hoy = hoje."},{"id":6303,"materia":"ling","nivel":2,"enunciado":"O alongamento antes de uma atividade física serve, principalmente, para:","opcoes":["Preparar músculos e articulações para o esforço","Aumentar a massa muscular na hora, durante o próprio jogo","Substituir o aquecimento cardiovascular sempre","Cansar o corpo antes do jogo"],"explicacao":"Ajuda a prevenir lesões."},{"id":6304,"materia":"mat","nivel":4,"enunciado":"Costuma-se dizer que o álcool compensa quando custa até 70% do preço da gasolina. Com gasolina a R$ 6,00 e álcool a R$ 4,50, compensa abastecer com:","opcoes":["Gasolina, pois o álcool custa 75% do preço dela","Álcool, pois é mais barato","Álcool, pois custa menos de 70% do preço da gasolina","Tanto faz, os preços são iguais"],"explicacao":"4,50 ÷ 6,00 = 0,75."},{"id":6305,"materia":"mat","nivel":2,"enunciado":"Um tênis custa R$ 300,00 à vista ou 3 parcelas de R$ 110,00. Quanto se paga de juros no parcelado?","opcoes":["R$ 30,00","R$ 10,00","R$ 110,00","R$ 3,00"],"explicacao":"3 × 110 = 330."},{"id":6306,"materia":"mat","nivel":2,"enunciado":"Uma escola tem 600 alunos, dos quais 45% são meninas. Quantos são meninos?","opcoes":["330","270","450","300"],"explicacao":"55% de 600."},{"id":6307,"materia":"mat","nivel":2,"enunciado":"Num mapa, 1 cm representa 2 km. Uma distância de 7,5 cm no mapa equivale a:","opcoes":["15 km","7,5 km","9,5 km","150 km"],"explicacao":"7,5 × 2."},{"id":6308,"materia":"mat","nivel":2,"enunciado":"Um terreno quadrado tem 81 m² de área. Seu perímetro é:","opcoes":["36 m","9 m","18 m","81 m"],"explicacao":"Lado 9 m; 4 × 9."},{"id":6309,"materia":"mat","nivel":2,"enunciado":"R$ 2.000,00 aplicados a juros simples de 3% ao mês rendem, em 4 meses:","opcoes":["R$ 240,00","R$ 60,00","R$ 120,00","R$ 2.240,00"],"explicacao":"2.000 × 0,03 × 4."},{"id":6310,"materia":"mat","nivel":3,"enunciado":"R$ 10.000,00 aplicados a juros compostos de 1% ao mês viram, em 2 meses:","opcoes":["R$ 10.201,00","R$ 10.200,00","R$ 10.020,00","R$ 12.000,00"],"explicacao":"10.000 × 1,01²."},{"id":6311,"materia":"mat","nivel":3,"enunciado":"Ao mesmo tempo, um prédio projeta sombra de 12 m e uma estaca de 2 m projeta sombra de 3 m. A altura do prédio é:","opcoes":["8 m","18 m","6 m","24 m"],"explicacao":"Semelhança: h/12 = 2/3."},{"id":6312,"materia":"mat","nivel":2,"enunciado":"Se x + y = 10 e x − y = 4, então x vale:","opcoes":["7","3","6","14"],"explicacao":"Somando: 2x = 14."},{"id":6313,"materia":"mat","nivel":3,"enunciado":"O número 2,5 milhões, em notação científica, é:","opcoes":["2,5 × 10⁶","2,5 × 10⁵","25 × 10⁶","2,5 × 10⁹"],"explicacao":"2.500.000."},{"id":6314,"materia":"mat","nivel":3,"enunciado":"Uma pessoa guarda R$ 100,00 no 1º mês e, a cada mês, R$ 50,00 a mais que no anterior. No 12º mês, ela guardará:","opcoes":["R$ 650,00","R$ 600,00","R$ 700,00","R$ 550,00"],"explicacao":"PA: 100 + 11 × 50."},{"id":6315,"materia":"fis","nivel":2,"enunciado":"Um objeto tem massa de 200 g e volume de 100 cm³. Sua densidade é:","opcoes":["2 g/cm³","0,5 g/cm³","20 g/cm³","300 g/cm³"],"explicacao":"d = m ÷ V."},{"id":6316,"materia":"fis","nivel":2,"enunciado":"Um aparelho de 2.000 W fica ligado por 30 minutos. Ele consome:","opcoes":["1 kWh","60 kWh","2 kWh","0,5 kWh"],"explicacao":"2 kW × 0,5 h."},{"id":6317,"materia":"fis","nivel":3,"enunciado":"O que consome mais energia: um ferro de 1.000 W ligado por 1 hora ou uma lâmpada de 10 W ligada por 10 horas?","opcoes":["O ferro (1 kWh contra 0,1 kWh)","A lâmpada","Os dois consomem igual","Nenhum consome energia"],"explicacao":"Energia = potência × tempo."},{"id":6318,"materia":"fis","nivel":3,"enunciado":"20 °C equivalem, na escala Fahrenheit, a:","opcoes":["68 °F","20 °F","36 °F","98 °F"],"explicacao":"F = 1,8 × 20 + 32."},{"id":6319,"materia":"fis","nivel":3,"enunciado":"Uma onda com frequência de 2 Hz tem período de:","opcoes":["0,5 s","2 s","4 s","1 s"],"explicacao":"T = 1 ÷ f."},{"id":6320,"materia":"fis","nivel":3,"enunciado":"A luz do Sol leva cerca de 8 minutos para chegar à Terra. Isso significa que vemos o Sol:","opcoes":["Como ele era 8 minutos antes","Exatamente como ele está agora","Como ele estará daqui a 8 minutos","Só à noite"],"explicacao":"A luz viaja a cerca de 300.000 km/s."},{"id":6321,"materia":"fis","nivel":4,"enunciado":"Numa gangorra em equilíbrio, uma criança de 30 kg senta a 2 m do apoio. Do outro lado, a 1,5 m do apoio, deve sentar uma criança de:","opcoes":["40 kg","30 kg","45 kg","20 kg"],"explicacao":"30 × 2 = m × 1,5."},{"id":6322,"materia":"qui","nivel":4,"enunciado":"200 mL de uma solução de 10 g/L recebem mais 200 mL de água. A nova concentração é:","opcoes":["5 g/L","10 g/L","20 g/L","2,5 g/L"],"explicacao":"A massa de soluto se mantém e o volume dobra."},{"id":6323,"materia":"qui","nivel":2,"enunciado":"Uma solução tem 5 g de sal em 100 g de solução. A porcentagem em massa de sal é:","opcoes":["5%","95%","50%","0,5%"],"explicacao":"5 ÷ 100."},{"id":6324,"materia":"qui","nivel":3,"enunciado":"Sabendo que a massa molar da água é 18 g/mol, 36 g de água correspondem a:","opcoes":["2 mol","18 mol","0,5 mol","36 mol"],"explicacao":"36 ÷ 18."},{"id":6325,"materia":"qui","nivel":2,"enunciado":"A fórmula do metano, principal componente do gás natural, é:","opcoes":["CH₄","CO₂","H₂O","NH₃"],"explicacao":"Um carbono e quatro hidrogênios."},{"id":6326,"materia":"qui","nivel":3,"enunciado":"À temperatura ambiente (25 °C), o mercúrio, usado em termômetros antigos, é:","opcoes":["Líquido","Sólido","Gasoso","Plasma"],"explicacao":"É o único metal líquido nessas condições."},{"id":6327,"materia":"qui","nivel":1,"enunciado":"A roupa molhada seca no varal porque a água passa por:","opcoes":["Evaporação","Condensação","Solidificação","Fusão"],"explicacao":"Passa do estado líquido para o gasoso."},{"id":6328,"materia":"qui","nivel":1,"enunciado":"As gotinhas de orvalho na grama, de manhã, se formam por:","opcoes":["Condensação do vapor d’água do ar","Evaporação da água que estava dentro da grama","Fusão do gelo","Sublimação"],"explicacao":"O vapor esfria e vira líquido."},{"id":6329,"materia":"qui","nivel":2,"enunciado":"O gás nobre que produz a luz avermelhada de letreiros luminosos é o:","opcoes":["Neônio","Oxigênio","Cloro","Hidrogênio"],"explicacao":"Daí o nome “luminoso de neon”."},{"id":6330,"materia":"bio","nivel":3,"enunciado":"Os animais que mantêm a temperatura do corpo constante, como aves e mamíferos, são chamados de:","opcoes":["Endotérmicos","Ectotérmicos","Decompositores","Produtores"],"explicacao":"Répteis e anfíbios são ectotérmicos."},{"id":6331,"materia":"bio","nivel":3,"enunciado":"Além dos pulmões, os anfíbios, como o sapo, também respiram:","opcoes":["Pela pele","Pelas brânquias, sempre","Pelo estômago","Pelos ossos"],"explicacao":"Respiração cutânea; por isso a pele precisa estar úmida."},{"id":6332,"materia":"bio","nivel":3,"enunciado":"Numa pirâmide de energia, a quantidade de energia disponível:","opcoes":["Diminui a cada nível trófico","Aumenta a cada nível","É igual em todos os níveis","Só existe nos consumidores"],"explicacao":"Parte da energia se perde como calor."},{"id":6333,"materia":"bio","nivel":2,"enunciado":"Fungos e bactérias decompositoras são importantes porque:","opcoes":["Devolvem os nutrientes da matéria morta ao ambiente","Produzem oxigênio como as plantas, pela fotossíntese","Caçam os predadores","Impedem a fotossíntese"],"explicacao":"Fecham o ciclo da matéria."},{"id":6334,"materia":"his","nivel":2,"enunciado":"Na Primeira Guerra Mundial, os soldados lutavam principalmente em longas valas cavadas no chão, chamadas:","opcoes":["Trincheiras","Bunkers nucleares","Muralhas","Fortes medievais"],"explicacao":"A “guerra de trincheiras” marcou o conflito."},{"id":6335,"materia":"geo","nivel":2,"enunciado":"Os tsunamis são causados, na maioria das vezes, por:","opcoes":["Terremotos no fundo do mar","Ventos fortes","Chuvas intensas","Marés de lua cheia"],"explicacao":"O deslocamento do fundo empurra grandes massas de água."},{"id":6336,"materia":"geo","nivel":2,"enunciado":"O Censo Demográfico do IBGE é feito, em regra, a cada:","opcoes":["10 anos","2 anos","50 anos","1 ano"],"explicacao":"O último foi realizado em 2022."},{"id":6337,"materia":"fil","nivel":3,"enunciado":"Num debate, alguém diz: “Não ouça o que ele fala sobre saúde, ele é feio e mal-educado”. Esse argumento é uma falácia:","opcoes":["Ad hominem (ataque à pessoa)","Válida e lógica","De autoridade legítima","Dedutiva perfeita"],"explicacao":"Ataca quem fala, não o argumento."},{"id":6338,"materia":"fil","nivel":3,"enunciado":"Concluir que “todos os cisnes são brancos” depois de ver muitos cisnes brancos é um raciocínio:","opcoes":["Indutivo","Dedutivo","Matemático exato","Impossível"],"explicacao":"Parte de casos particulares para uma regra geral."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
